  expectedN=N0.astype(float).copy();expectedN[domain]=normals(q1,tri)[domain];actualN=N1.astype(float)+dn;normalError=float(np.linalg.norm(expectedN-actualN,axis=1).max());check(normalError<2e-7 and np.isfinite(actualN).all(),name+' normal mismatch/nonfinite');check(np.array_equal(actualN[fixedN],N0[fixedN]),name+' outside normal changed')
  cos=np.sum(actualN[domain]*N0[domain],axis=1)/np.maximum(np.linalg.norm(actualN[domain],axis=1)*np.linalg.norm(N0[domain],axis=1),1e-30)
